+        var existingIdx = _threadSummaries.FindIndex(t => t.RootMessageId == _threadRootMessage.Id);
+        var summary = new ThreadSummary(_threadRootMessage.Id, _threadReplies.Count, reply.SentAt);
+        if (existingIdx >= 0)
+            _threadSummaries[existingIdx] = summary;
+        else
+            _threadSummaries.Add(summary);
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+        // Refresh messages to reflect updated reactions
+        if (_activeChannel is not null)
+        {
+            _messages = await ChatService.GetMessagesAsync(_activeChannel.Id, 0, _messages.Count);
+        }
+    }
+
+    private async Task LoadOlderMessages()
+    {
+        if (_activeChannel is null || _isLoadingMore) return;
+        _isLoadingMore = true;
+        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _messages.Count, PageSize);
+        if (older.Count > 0)
+        {
+            _messages.InsertRange(0, older);
+            _threadSummaries = BuildThreadSummaries(_messages);
+        }
+        _isLoadingMore = false;
+    }
+
+    private static List<ThreadSummary> BuildThreadSummaries(List<Message> messages)
+    {
+        // Build thread summaries from messages that have replies
+        var rootIds = messages
+            .Where(m => m.ReplyToId.HasValue)
+            .GroupBy(m => m.ReplyToId!.Value)
+            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
+            .ToList();
+        return rootIds;
+    }
+}
